insert into public.ukweli_knowledge (slug, topic, question, keywords, answer, language, source, source_url, sensitive, sort_order) values
('bodies-vary-sw','body-image',$q$Kuna tatizo na jinsi sehemu zangu za siri zinavyoonekana?$q$,
 array['kawaida','kuma','uume','inaonekanaje','ukubwa','mbaya','ndogo'],
 $q$Hakuna "kawaida" moja — kuma, midomo ya uke, uume, matiti na rangi ya ngozi vinakuja kwa maumbo, ukubwa na rangi tofauti, na mara nyingi kinachoonekana "kizuri kabisa" mtandaoni kimehaririwa au kubadilishwa. Midomo iliyolegea au isiyolingana, pumbu moja kuwa chini ya lingine, uume uliopinda kidogo, ngozi nyeusi kuzunguka sehemu za siri, au matiti ya ukubwa tofauti — yote ni ya kawaida na yenye afya. Jinsi uume unavyoonekana ukiwa umelala haionyeshi ukubwa wake ukiwa umesimama, na "ukubwa" sio muhimu kwa raha au uzazi kama watu wanavyodai. Kinachostahili kuonana na daktari ni mabadiliko unayoweza kuhisi au kuona — uvimbe mpya, kidonda, majimaji yasiyo ya kawaida, harufu kali, kuwashwa au maumivu — kwa sababu hayo yaweza kuwa dalili za maambukizi yanayotibika kwa urahisi. Kuonekana tofauti sio kasoro; ni mwili tu, na karibu kila mtu huwa na wasiwasi kimya kwamba wake ni wa ajabu wakati sio.$q$,'sw','WHO','https://www.who.int/health-topics/sexual-health',false,10),

('masturbation-safe-sw','masturbation',$q$Je, kujichua kutaniumiza?$q$,
 array['kujichua','punyeto','kujigusa','masturbation'],
 $q$Hapana — kujichua ni kawaida na hakuna madhara kiafya. Hakusababishi upofu, ugumba, udhaifu, chunusi, "kupoteza nguvu", wala ugonjwa wowote, na watu wa jinsia zote hufanya. Hakuna hatari ya mimba wala magonjwa ya zinaa, na kwaweza kukusaidia kuelewa mwili wako, kupunguza msongo na kulala vizuri. Kufanya mara kwa mara ni sawa; hakuna "kupita kiasi" ilimradi hakukuumizi wala kukuzuia shule, marafiki au majukumu. Kama kutaanza kuhisi kama uraibu, au unakitumia tu kukimbia msongo, ni vyema kuzungumza na mtu unayemwamini. Chochote ulichoambiwa ili kukutisha, hakuna uchafu wala uharibifu ndani yake.$q$,'sw','WHO','https://www.who.int/health-topics/sexual-health',false,20),

('sexual-feelings-normal-sw','sexual-feelings',$q$Ni kawaida kuhisi hamu ya ngono mara kwa mara?$q$,
 array['hamu','ashiki','hisia za ngono','nyege'],
 $q$Ndiyo — kuhisi mvuto, ashiki, udadisi au hamu kali, wakati mwingine ghafla, ni sehemu ya kawaida ya kubalehe, inayoendeshwa na homoni na ni ya kibinadamu kabisa. Hisia hizi huja na kuondoka, zaweza kuwa kuhusu watu usingewahi kuwafikia, na hazikufanyi mtu mbaya au mchafu. Jambo muhimu zaidi ni kwamba hisia na vitendo ni tofauti: una uhuru daima wa kuchagua unachofanya, lini, na na nani — au kutofanya kabisa. Hakuna "umri sahihi" wa kuanza kuhisi hivi na hakuna aibu kuhisi sana au kidogo. Kama hisia zitakulemea au kukuchanganya, kuzungumza na mtu unayemwamini kwaweza kukusaidia kuzielewa bila hukumu.$q$,'sw',null,null,false,30),

('same-sex-feelings-sw','identity',$q$Nina hisia kwa mtu wa jinsia yangu — kuna tatizo nami?$q$,
 array['mashoga','wasagaji','jinsia moja','ngono ya jinsia moja'],
 $q$Hakuna tatizo, hukuharibika wala hukutenda dhambi — kuvutiwa na jinsia yako, na jinsia zaidi ya moja, au kutokuwa na uhakika ni sehemu ya hali ya kawaida ya binadamu ambayo mamilioni ya watu hushiriki. Huna haja ya kujibandika lebo, "kuthibitisha" lolote, kujitangaza, au kufanya uamuzi sasa; hisia zaweza kuwa wazi au za kutatanisha na zaweza kubadilika kwa wakati, na yote ni sawa. Unachohisi ni halisi na halali hata kama watu kuzunguka hawakuelewi, na hakisemi lolote baya kuhusu tabia yako. Usalama na afya yako huja kwanza, kwa hivyo chagua kwa uangalifu unayemweleza, na enda kwa kasi yako. Kama hili linakulemea, mshauri asiyehukumu au mtu mzima unayemwamini aweza kuwa msaada — na chochote unachohisi, hauko peke yako na unastahili heshima.$q$,'sw',null,null,true,40),

('gender-identity-sw','identity',$q$Vipi kama sihisi kuwa mvulana au msichana kikamilifu?$q$,
 array['jinsia','utambulisho','mvulana au msichana','trans'],
 $q$Utambulisho wa kijinsia ni hisia yako ya ndani ya kuwa mvulana, msichana, vyote, hakuna, au mahali katikati — na kwa baadhi ya watu haulingani na jinsia iliyoandikwa wakati wa kuzaliwa, jambo ambalo ni uzoefu halisi wa kibinadamu uliotambuliwa kwa muda mrefu, sio mtindo wala ugonjwa. Waweza kuhisi hivi kwa nguvu au kuwa unajiuliza tu, na vyote ni sawa; hakuna muda uliowekwa wala kitu lazima uamue leo. Kuhisi hivi hakumaanishi kuna kitu kibaya nawe, na hakuhitaji kubadilisha jinsi unavyoishi sasa isipokuwa ukitaka. Kwa kuwa si kila mtu kuzunguka ataelewa, ni busara kufikiria ni nani salama kuzungumza naye na kwenda kwa kasi yako. Mshauri rafiki kwa vijana aweza kukupa nafasi ya faragha, isiyohukumu kuchunguza unachohisi — hisia zako ni halali, haijalishi maneno gani unatumia au hutumii.$q$,'sw',null,null,true,50),

('sharing-toys-sw','safer-sex',$q$Ni salama kushiriki vifaa vya ngono au strap-on?$q$,
 array['kifaa cha ngono','strap on','vibrator','kushiriki vifaa'],
 $q$Kushiriki vifaa vya ngono kwaweza kusambaza magonjwa ya zinaa (kama herpes, HPV, kisonono, klamidia na homa ya ini) na kuvuruga uwiano wa asili unaosababisha maambukizi kama bacterial vaginosis na fangasi, kwa sababu majimaji ya mwili hubaki kwenye kifaa. Chaguo salama zaidi ni kutoshiriki; ukishiriki, vaa kondomu mpya kwenye kifaa na ibadilishe kabla ya mtu anayefuata, na osha kifaa kwa maji ya uvuguvugu na sabuni, kisha ikauke, kati ya matumizi. Kamwe usihamishe kifaa moja kwa moja kutoka njia ya haja kubwa kwenda ukeni au mdomoni bila kukisafisha na kubadilisha kondomu, kwa sababu hilo husambaza bakteria. Tumia lubricant ya maji au silicone ili kuepuka michaniko midogo inayoruhusu maambukizi, na hakikisha vifaa ni salama kwa mwili na havijaharibika. Kanuni hizi hizi — vizuizi, kutoshiriki majimaji, na kusafisha kati — ndizo hufanya kila aina ya ngono kuwa salama zaidi.$q$,'sw','WHO','https://www.who.int/health-topics/sexually-transmitted-infections',true,60),

('drugs-and-sex-sw','harm-reduction',$q$Ni hatari kuchanganya pombe au dawa za kulevya na ngono?$q$,
 array['kulewa','dawa za kulevya','pombe','bangi'],
 $q$Ndiyo, kuchanganya pombe au dawa za kulevya na ngono huongeza hatari halisi. Kuwa umelewa au umepiga dawa hupotosha uamuzi, kwa hivyo watu husahau au huruka kondomu, hukosea hali, na huwa na uwezekano zaidi wa kujuta baadaye — na muhimu zaidi, mtu aliyelewa sana hawezi kutoa ridhaa ya kweli, maana yake ngono naye si sawa, na kanuni hiyo hiyo inakulinda wewe pia. Mchanganyiko fulani ni hatari kimwili (kwa mfano pombe au dawa pamoja na vidonge vya nguvu za kiume, au kuchanganya dawa za usingizi), na dawa zaweza pia kufanya kusimama, kufika kileleni au ulainisho kuwa vigumu. Ukinywa au ukatumia, tabia chache hupunguza madhara: beba kondomu, linda kinywaji chako, kaa na watu unaowaamini, kubaliana mipaka kabla, na kumbuka waweza kusimama au kuondoka wakati wowote. Hudaiwi ngono na mtu kwa sababu alikununulia vinywaji au mlipiga dawa pamoja.$q$,'sw',null,null,false,70),

('anal-sex-safety-sw','safer-sex',$q$Ngono ya njia ya haja kubwa ni salama?$q$,
 array['njia ya nyuma','anal','haja kubwa'],
 $q$Ngono ya njia ya haja kubwa yaweza kufanywa kwa usalama zaidi, lakini ina hatari kubwa zaidi ya HIV na magonjwa ya zinaa kuliko aina nyingine za ngono, kwa sababu utando wa ndani ni mwembamba na huchanika kwa urahisi, ukiruhusu maambukizi kuingia. Ili kupunguza hatari: tumia kondomu daima pamoja na lubricant ya maji au silicone kwa wingi (njia hii haitengenezi ulainisho wake, na lubricant huzuia michaniko midogo), nenda polepole, na simama kukiwa na maumivu au damu. Kamwe usiende kutoka haja kubwa kwenda ukeni bila kubadilisha kondomu, ili kuepuka kusambaza bakteria na maambukizi ya mkojo, na huhitaji "kusafisha ndani" au kufanya douche — hilo huwasha utando na laweza kuongeza hatari. Kondomu pia ni muhimu kwa sababu shahawa ikifika ukeni baadaye yaweza kusababisha mimba. Kama unafanya hivi mara kwa mara, ni vyema kuuliza kliniki kuhusu PrEP na vipimo vya mara kwa mara.$q$,'sw','NASCOP','https://www.nascop.or.ke',true,80),

('what-is-consent-sw','consent',$q$Ni nini hasa huhesabika kama ridhaa?$q$,
 array['ridhaa','shinikizo','lazimisha','ndio'],
 $q$Ridhaa ni "ndiyo" iliyo wazi, iliyotolewa kwa hiari na kwa shauku, nayo huhesabika tu pale mtu akiwa na akili timamu, macho, umri wa kutosha, na bila shinikizo, vitisho au hofu. Ni mahususi (ndiyo kwa jambo moja sio ndiyo kwa yote), inaendelea (waweza kubadilisha nia wakati wowote, hata katikati), na inahitajika kila mara — ikiwemo na mpenzi au mwenzi wa ndoa. Ukimya, kukubali tu, au kutopigana sio ridhaa, na wala sio "ndiyo" iliyotolewa kwa kulazimishwa, kusumbuliwa, au maneno kama "kama ungenipenda". Ridhaa ya kweli huenda pande zote mbili: unahakikisha mwenzako anataka kweli, nawe una uhuru wa kusema hapana, "bado", au "acha" wakati wowote bila kutoa sababu. Mtu akipuuza hapana yako au akikusukuma, kosa ni lake, kamwe sio lako.$q$,'sw',null,null,false,90),

('after-unprotected-sex-sw','emergency',$q$Nimefanya ngono bila kinga — nifanye nini sasa?$q$,
 array['bila kinga','kondomu ilipasuka','kuzuia mimba','pep','p2','postinor'],
 $q$Tenda haraka, kwa sababu njia zako hufanya kazi vizuri ndani ya saa chache. Kuzuia mimba, kidonge cha dharura — kinachouzwa Kenya bila cheti kwenye maduka ya dawa kama P2, Postinor-2 au Ecee-2 — hufanya kazi vizuri ndani ya saa 72, huku aina fulani na kitanzi cha shaba (kinachowekwa kliniki) zikifanya kazi hadi saa 120 (siku 5); mapema ni bora. Kuzuia HIV, PEP ni dawa za kozi fupi ambazo lazima zianze ndani ya saa 72 baada ya kuathiriwa — nenda hospitali, kituo cha afya au VCT uombe kwa jina. Kliniki pia yaweza kupima na kutibu magonjwa mengine ya zinaa, na kama hedhi itachelewa, pima mimba baada ya majuma matatu hivi. Huhitaji ruhusa ya mzazi kuuliza, na kliniki rafiki kwa vijana hushughulikia haya kila siku bila hukumu.$q$,'sw','NASCOP','https://www.nascop.or.ke',false,100),

('protect-from-hiv-sw','hiv',$q$Nawezaje kujikinga na HIV?$q$,
 array['hiv','prep','kujikinga','ukimwi','u=u'],
 $q$Una njia kadhaa imara, na kuchanganya hufanya kazi vizuri zaidi. Kondomu ukitumia vizuri kila mara ni bora sana dhidi ya HIV na pia huzuia magonjwa mengine ya zinaa na mimba, kwa hivyo ndiyo msingi wa kila siku. PrEP — kidonge cha kila siku kinachotolewa bure kupitia kliniki nyingi za Kenya kwa njia ya NASCOP — kinaweza kuzuia HIV kabla ya kuathiriwa kama uko katika hatari zaidi, kwa mfano kama mpenzi anaishi na HIV au una wapenzi zaidi ya mmoja. Kujua hali yako ni muhimu: kupima HIV ni haraka, bure na kwa siri katika vituo rafiki kwa vijana, na vifaa vya kujipima vipo pia. Ukiathiriwa, PEP iliyoanza ndani ya saa 72 bado yaweza kuzuia maambukizi. Na ukweli mmoja unaobadilisha kila kitu: mtu anayeishi na HIV anayetumia dawa zake na ana kiwango cha virusi kisichoonekana hawezi kuambukiza HIV kingono — hiyo ni "U=U", Isiyoonekana ni Isiyoambukiza.$q$,'sw','NASCOP','https://www.nascop.or.ke',false,110),

('am-i-pregnant-sw','pregnancy',$q$Nitajuaje kama nina mimba?$q$,
 array['mimba','sijaona hedhi','kipimo cha mimba','hedhi imechelewa'],
 $q$Dalili ya kwanza ya kawaida ni hedhi kukosekana au kuchelewa sana, na baadhi ya watu pia huhisi matiti kuuma au kuvimba, kichefuchefu, uchovu usio wa kawaida, kukojoa mara nyingi, au kutokwa na matone kidogo — lakini msongo, ugonjwa na homoni vyaweza kusababisha yote haya, kwa hivyo dalili peke yake hazithibitishi. Njia pekee ya uhakika ni kipimo cha mimba: vifaa vya kupima mkojo ni rahisi na huuzwa katika duka lolote la dawa Kenya, na ni sahihi zaidi kuanzia siku ya kwanza hedhi inapotarajiwa, au majuma matatu hivi baada ya ngono bila kinga. Fuata maelekezo, tumia mkojo wa asubuhi kwa jibu wazi, na kama kipimo ni hasi lakini hedhi bado haiji, pima tena baada ya juma au tembelea kliniki. Jibu lolote lile, kliniki rafiki kwa vijana yaweza kukueleza chaguo zako kwa faragha na bila hukumu — hauko peke yako wala hulazimiki kuamua papo hapo.$q$,'sw',null,null,false,120),

('porn-vs-reality-sw','media',$q$Je, ngono halisi ni kama ninayoiona kwenye ponografia?$q$,
 array['ponografia','ngono kama','xvideos'],
 $q$Hapana — ponografia ni burudani iliyotengenezwa, sio uhalisia. Waigizaji huchaguliwa kwa sura fulani, matukio huandikwa, huwekewa mwanga na kuhaririwa, miili mara nyingi hubadilishwa kwa upasuaji, na "uvumilivu" unaouona ni makato, mapumziko na wakati mwingine dawa. Ngono halisi ni ya polepole zaidi, ya aibu kidogo, ya kimya na yenye tofauti: miili huonekana ya kawaida, si kila mtu hufika kileleni, kusimama na ulainisho havipatikani kwa amri, na ridhaa na mazungumzo ambayo ponografia huruka ndiyo hufanya iwe nzuri. Kuichukulia kama mwongozo huzua wasiwasi usio wa lazima kuhusu ukubwa, uwezo na muda, na laweza kusukuma watu kutarajia au kulazimisha wenzao mambo wasiyoyataka. Kuiangalia hakukufanyi mbaya — jambo kuu ni kutoichukulia maonyesho kama maisha halisi au kama deni la mwenzako.$q$,'sw',null,null,false,130),

('pressured-for-nudes-sw','safety',$q$Mtu ananisukuma nimtumie picha za uchi.$q$,
 array['picha za uchi','nudes','kutuma picha','sextortion'],
 $q$Humdai mtu yeyote picha — si mpenzi, si mkubwa, si anayeahidi mapenzi, pesa au siri — na heshima ya kweli ni kusikia "hapana" mara ya kwanza. Picha ikiondoka kwenye simu yako unapoteza udhibiti wote: yaweza kuhifadhiwa, kusambazwa au kutumika kukutisha, ikiwemo picha zilizotumwa kwa programu za "kujifuta". Yeyote anayekusukuma, kukushinikiza au kukutisha ili apate picha — au kutishia kutoa ulizotuma tayari (hiyo ni sextortion) — ndiye aliye na kosa, na sio lako, hata kama ulituma kitu awali. Usitume zaidi na usilipe; kulipa karibu kila mara huleta madai zaidi. Badala yake, hifadhi ushahidi, mzuie, na mweleze mtu mzima unayemwamini — na Kenya waweza kupiga simu ya Childline bure kwa 116. Una haki ya kusema hapana na haki ya kupata msaada.$q$,'sw',null,null,false,140)
on conflict (slug) do update set
  answer = excluded.answer, keywords = excluded.keywords, question = excluded.question;


insert into public.ukweli_knowledge (slug, topic, question, keywords, answer, language, source, source_url, sensitive, sort_order) values
('bodies-vary-sh','body-image',$q$Kuna shida na vile sehemu zangu za siri zinaonekana?$q$,
 array['kawaida','kuma','mboro','inaonekanaje','size','mbaya'],
 $q$Hakuna "normal" moja — kuma, lips za uke, mboro, maziwa na rangi ya ngozi zinakuja na shapes, size na rangi tofauti, na mob ya vile vitu zina-look "perfect" online zime-edit ama zimebadilishwa. Lips zimelegea ama hazilingani, pumbu moja iko chini ya ingine, mboro imepinda kidogo, ngozi nyeusi around sehemu za siri, ama maziwa za size tofauti — zote ni kawaida na healthy. Vile mboro inaonekana ikiwa imelala hai-show size yake ikisimama, na "size" si muhimu kwa raha ama kuzaa vile watu wanaclaim. Kitu inastahili uone daktari ni change unaweza feel ama ona — lump mpya, kidonda, discharge ngeni, harufu kali, kuwashwa ama maumivu — sababu hizo zinaweza kuwa dalili za infection inatibika easy. Kuonekana different si kasoro; ni mwili tu, na karibu kila mtu ana-worry kimya kuwa yake ni ngeni wakati si.$q$,'sheng','WHO','https://www.who.int/health-topics/sexual-health',false,10),

('masturbation-safe-sh','masturbation',$q$Je, kujichua kutaniumiza?$q$,
 array['kujichua','punyeto','masturbation','kujiguza'],
 $q$Hapana — kujichua ni kawaida na hakuna madhara ki-afya. Haileti upofu, ugumba, udhaifu, pimples, "kupoteza nguvu", wala ugonjwa wowote, na watu wa jinsia zote wanafanya. Hakuna risk ya mimba ama STI, na inaweza kusaidia ujue mwili wako, u-relax na ulale poa. Kufanya mara kwa mara ni sawa; hakuna "too much" ilimradi haikuumizi wala haiku-stop shule, marafiki ama majukumu. Ikianza ku-feel kama addiction, ama unaitumia tu ku-escape stress, ni poa kuongea na mtu una-trust. Chochote uliambiwa ili ukuogopeshwe, hakuna uchafu wala damage ndani yake.$q$,'sheng','WHO','https://www.who.int/health-topics/sexual-health',false,20),

('sexual-feelings-normal-sh','sexual-feelings',$q$Ni kawaida kuhisi nyege mara kwa mara?$q$,
 array['nyege','hamu','feelings za ngono','horny'],
 $q$Ndio — kuhisi attraction, nyege, curiosity ama hamu kali, wakati zingine ghafla, ni part ya kawaida ya ku-grow, inaendeshwa na hormones na ni ki-binadamu kabisa. Hizi feelings zinakuja na kuenda, zinaweza kuwa kuhusu watu usingewahi approach, na hazikufanyi mtu mbaya ama mchafu. Kitu muhimu zaidi ni kuwa feelings na actions ni tofauti: una freedom daima ku-choose unafanya nini, lini, na na nani — ama kutofanya kabisa. Hakuna "right age" ya kuanza kufeel hivi na hakuna aibu kufeel sana ama kidogo. Kama feelings zina-overwhelm ama zina-confuse, kuongea na mtu una-trust inaweza kusaidia uzielewe bila judgment.$q$,'sheng',null,null,false,30),

('same-sex-feelings-sh','identity',$q$Niko na feelings kwa mtu wa jinsia yangu — kuna shida na mimi?$q$,
 array['gay','lesbian','same sex','queer','jinsia moja'],
 $q$Hakuna shida, hukuharibika wala hukutenda dhambi — ku-attracted na jinsia yako, na jinsia zaidi ya moja, ama kutokuwa sure ni part ya hali ya kawaida ya binadamu ambayo millions ya watu wana-share. Huna haja ya ku-label, "ku-prove" kitu, ku-come out, ama kufanya decision sahii; feelings zinaweza kuwa clear ama confusing na zinaweza badilika na time, na zote ni sawa. Unachofeel ni real na valid hata kama watu around hawakuelewi, na haisemi kitu mbaya kuhusu character yako. Safety na wellbeing yako zinakuja kwanza, so chagua carefully unamwambia nani, na enda kwa pace yako. Kama hii inaku-weigh down, counsellor asiye-judge ama mtu mzima una-trust anaweza kuwa support — na chochote unafeel, hauko peke yako na unastahili respect.$q$,'sheng',null,null,true,40),

('gender-identity-sh','identity',$q$Aje kama sifeel kuwa mvulana ama msichana fully?$q$,
 array['gender','identity','trans','mvulana ama msichana'],
 $q$Gender identity ni feeling yako ya ndani ya kuwa mvulana, msichana, zote, hakuna, ama mahali katikati — na kwa watu wengine hai-match jinsia iliyoandikwa ukizaliwa, kitu ambacho ni experience ya kweli ya binadamu iliyotambuliwa kwa muda mrefu, si trend wala ugonjwa. Unaweza feel hivi strong ama uwe unajiuliza tu, na zote ni sawa; hakuna timeline wala kitu lazima u-decide leo. Kufeel hivi haimaanishi kuna kitu mbaya na wewe, na hailazimu u-change vile unaishi sahii unless utake. Sababu si kila mtu around ataelewa, ni busara u-think ni nani safe kuongea naye na uende kwa pace yako. Counsellor friendly kwa vijana anaweza kukupa nafasi ya private, isiyo-judge ku-explore unachofeel — feelings zako ni valid, haijalishi maneno gani unatumia ama hutumii.$q$,'sheng',null,null,true,50),

('sharing-toys-sh','safer-sex',$q$Ni safe ku-share sex toys ama strap-on?$q$,
 array['sex toy','strap on','vibrator','ku-share toys'],
 $q$Ku-share sex toys inaweza kusambaza STI (kama herpes, HPV, kisonono, chlamydia na hepatitis) na ku-disturb balance ya asili inayoleta infections kama BV na fungus, sababu fluids za mwili zinabaki kwa toy. Option safe zaidi ni kutosha-share; ukisha-share, vaa condom fresh kwa toy na ubadilishe mpya kabla ya mtu anayefuata, na osha toy na maji ya uvuguvugu na sabuni, halafu ikauke, kati ya matumizi. Usiwahi hamisha toy direct kutoka nyuma (anal) kwenda uke ama mdomo bila ku-clean na ku-change condom, sababu hiyo inasambaza bacteria. Tumia lube ya maji ama silicone mob ili kuepuka michaniko ndogo zinazo-ruhusu infection, na hakikisha toys ni body-safe na hazijaharibika. Hizi principles zenyewe — barriers, kutosha-share fluids, na ku-clean kati — ndio zinafanya kila aina ya ngono kuwa safer.$q$,'sheng','WHO','https://www.who.int/health-topics/sexually-transmitted-infections',true,60),

('drugs-and-sex-sh','harm-reduction',$q$Ni risky ku-mix pombe ama drugs na ngono?$q$,
 array['level','drugs','pombe','ngedo','high'],
 $q$Ndio, ku-mix pombe ama drugs na ngono inaongeza risk ya kweli. Kuwa drunk ama high ina-blur judgment, so watu wanasahau ama wana-skip condom, wana-misread situation, na wako likely ku-regret baadaye — na muhimu zaidi, mtu aliye drunk ama high sana hawezi kutoa consent ya kweli, maana yake ngono naye si sawa, na rule hiyo hiyo inaku-protect wewe pia. Mixtures zingine ni hatari ki-mwili (mfano pombe ama drugs pamoja na vidonge vya nguvu, ama ku-mix sedatives), na drugs zinaweza fanya erection, orgasm ama lubrication kuwa ngumu. Ukikunywa ama utumie, habits chache zina-reduce harm: beba condom, linda drink yako, kaa na watu una-trust, kubaliana limits kabla, na kumbuka unaweza stop ama uondoke wakati wowote. Hudaiwi ngono na mtu sababu alikununulia drinks ama mlipiga high pamoja.$q$,'sheng',null,null,false,70),

('anal-sex-safety-sh','safer-sex',$q$Anal sex ni safe?$q$,
 array['anal','nyuma','backdoor'],
 $q$Anal sex inaweza fanywa safer, lakini ina risk kubwa zaidi ya HIV na STI kuliko aina zingine za ngono, sababu lining ya ndani ni nyembamba na inachanika easy, ikiruhusu infection kuingia. Ku-lower risk: tumia condom daima na lube ya maji ama silicone mob (sehemu hii haitengenezi lubrication yake, na lube inazuia michaniko ndogo), enda pole pole, na stop kukiwa na maumivu ama damu. Usiwahi enda kutoka nyuma kwenda uke bila ku-change condom, ili kuepuka kusambaza bacteria na UTI, na huhitaji "ku-flush" ndani ama ku-douche — hiyo inawasha lining na inaweza ongeza risk. Condom pia ni muhimu sababu shahawa ikifika uke baadaye inaweza leta mimba. Kama unafanya hii mara kwa mara, ni poa kuuliza clinic kuhusu PrEP na STI test za mara kwa mara.$q$,'sheng','NASCOP','https://www.nascop.or.ke',true,80),

('what-is-consent-sh','consent',$q$Ni nini hasa inahesabika kama consent?$q$,
 array['consent','pressure','kulazimisha','ndio'],
 $q$Consent ni "ndio" iliyo clear, imetolewa kwa hiari na kwa enthusiasm, na inahesabika tu mtu akiwa sober, awake, na age ya kutosha, na bila pressure, vitisho ama hofu. Ni specific (ndio kwa kitu kimoja si ndio kwa kila kitu), inaendelea (unaweza badilisha mind wakati wowote, hata katikati), na inahitajika kila mara — ikiwemo na bae ama mwenzi wa ndoa. Silence, kukubali tu, ama kutopigana si consent, na wala si "ndio" iliyotolewa kwa guilt-trip, ku-pester, ama lines kama "kama ungenipenda". Consent ya kweli inaenda pande zote mbili: una-check mwenzako anataka kweli, na uko na freedom ya kusema no, "bado", ama "acha" wakati wowote bila kutoa reason. Mtu aki-ignore no yako ama aku-push, kosa ni lake, si lako kamwe.$q$,'sheng',null,null,false,90),

('after-unprotected-sex-sh','emergency',$q$Nime-fanya ngono bila protection — nifanye aje sahii?$q$,
 array['bila protection','condom ilipasuka','kuzuia mimba','pep','p2','postinor'],
 $q$Fanya haraka, sababu options zako zina-work best ndani ya masaa. Kuzuia mimba, emergency pill — inauzwa Kenya bila prescription kwa chemist kama P2, Postinor-2 ama Ecee-2 — ina-work best ndani ya masaa 72, na aina zingine na copper IUD (inawekwa clinic) zina-work hadi masaa 120 (siku 5); mapema ni poa zaidi. Kuzuia HIV, PEP ni dawa za course fupi ambazo lazima zianze ndani ya masaa 72 baada ya exposure — enda hospitali, health centre ama VCT uombe kwa jina. Clinic pia inaweza ku-test na ku-treat STI zingine, na kama period ita-delay, pima mimba baada ya wiki tatu hivi. Huhitaji permission ya mzazi kuuliza, na clinic friendly kwa vijana zina-handle hizi kila siku bila judgment.$q$,'sheng','NASCOP','https://www.nascop.or.ke',false,100),

('protect-from-hiv-sh','hiv',$q$Naweza jikinga aje na HIV?$q$,
 array['hiv','prep','kujikinga','ukimwi','u=u'],
 $q$Uko na tools kadhaa strong, na ku-combine ina-work best. Condom ukitumia vizuri kila mara ni effective sana dhidi ya HIV na pia inazuia STI zingine na mimba, so ndio foundation ya kila siku. PrEP — kidonge cha kila siku kinachotolewa free kupitia clinic nyingi za Kenya kwa njia ya NASCOP — kinaweza kuzuia HIV kabla ya exposure kama uko kwa risk zaidi, mfano kama bae anaishi na HIV ama uko na mabae zaidi ya mmoja. Kujua status yako ni muhimu: ku-test HIV ni haraka, free na confidential kwa centres friendly kwa vijana, na self-test kits ziko pia. Uki-exposed, PEP iliyoanza ndani ya masaa 72 bado inaweza kuzuia infection. Na fact moja ina-change kila kitu: mtu anayeishi na HIV anayetumia dawa zake na ako na viral load isiyoonekana hawezi ku-transmit HIV ki-ngono — hiyo ni "U=U", Undetectable ni Untransmittable.$q$,'sheng','NASCOP','https://www.nascop.or.ke',false,110),

('am-i-pregnant-sh','pregnancy',$q$Nitajua aje kama niko na mimba?$q$,
 array['mimba','sijaona period','pregnancy test','period imechelewa'],
 $q$Dalili ya kwanza ya kawaida ni period ku-miss ama ku-delay sana, na watu wengine pia wanafeel maziwa yakiuma ama kuvimba, nausea, uchovu ngeni, kukojoa mara mingi, ama spotting kidogo — lakini stress, ugonjwa na hormones zinaweza leta zote hizi, so dalili peke yake hazi-confirm. Njia pekee ya uhakika ni pregnancy test: urine kits ni rahisi na zinauzwa kwa chemist yoyote Kenya, na ni accurate zaidi kuanzia siku ya kwanza period inatarajiwa, ama wiki tatu hivi baada ya ngono bila protection. Follow instructions, tumia urine ya asubuhi kwa result clear, na kama test ni negative lakini period bado haiji, pima tena baada ya wiki ama enda clinic. Result yoyote, clinic friendly kwa vijana inaweza kukueleza choices zako kwa private na bila judgment — hauko peke yako wala hulazimiki ku-decide papo hapo.$q$,'sheng',null,null,false,120),

('porn-vs-reality-sh','media',$q$Je, ngono halisi iko kama ninaona kwa porn?$q$,
 array['porn','ponografia','xvideos','ngono kama'],
 $q$Hapana — porn ni entertainment iliyo-produced, si documentary. Actors wanachaguliwa kwa looks fulani, scenes zina-script, zina-light na ku-edit, miili mara nyingi ime-alter ki-upasuaji, na "stamina" unaona ni cuts, breaks na wakati zingine dawa. Ngono halisi iko slower, ya aibu kidogo, quiet na varied: miili inaonekana ya kawaida, si kila mtu ana-finish, erection na lubrication haziji kwa amri, na consent na communication ambazo porn ina-skip ndio zina-make iwe poa. Ku-treat porn kama how-to guide ina-fuel anxiety isiyo ya lazima kuhusu size, performance na muda, na inaweza push watu ku-expect ama ku-pressure wenzao vitu wasivyotaka. Ku-watch haikufanyi mbaya — key ni kutochukua performance kama real life ama kama deni la mwenzako.$q$,'sheng',null,null,false,130),

('pressured-for-nudes-sh','safety',$q$Mtu ananipressure nimtumie nudes.$q$,
 array['nudes','nude','sexting','kutuma pics','sextortion'],
 $q$Hudai mtu yoyote picha — si bae, si mkubwa, si anaye-promise love, doo ama siri — na respect ya kweli ni kusikia "no" mara ya kwanza. Picha ikitoka kwa simu yako una-lose control yote: inaweza save-iwa, forward-iwa ama kutumika ku-threaten, ikiwemo pics zilizo-send kwa apps za "ku-disappear". Yeyote anaye-pressure, ku-guilt-trip ama ku-threaten ili apate pics — ama ku-threaten ku-leak ulizo-send already (hiyo ni sextortion) — ndiye ako wrong, si wewe, hata kama uli-send kitu awali. Usi-send zaidi na usilipe; kulipa karibu kila mara inaleta demands zaidi. Badala yake, save evidence, mu-block, na mwambie mtu mzima una-trust — na Kenya unaweza piga Childline free kwa 116. Uko na right ya kusema no na right ya kupata help.$q$,'sheng',null,null,false,140)
